// 11.10.2026 подтверждено на iPhone (F-91 עבר QA): в ספרד стр.3/4 «אין הקראה לקטע הזה», «השמע» неактивна; смена נוסח — окно «להחליף את התפילה לנוסח ספרד?» → «החלף».
// Тикеты #6a86f7eda7b2 (F-91) и #6a86f7ed9d38 (F-92), проверены на web 07.10.2026: запись ערבית אשכנז קטע 3 в נוסח ספרד не предлагается
// (скрины rec-E1-user-arvit-sfarad-s3-no-ashkenaz-recording, rec-E2-user-arvit-sfarad-header). pending-app-2026-10-07.md п.6.
// Опора: F-91 AC2 «ההקראה מתייחסת לטקסט המוצג באותו רגע ובנוסח המוצג»; F-92 AC3 «כל הקלטה מקושרת לטקסט ולנוסח שהיא קוראת»; S-33 AC5.
// ПРЕДУСЛОВИЕ: утверждённая запись на ערבית אשכנז קטע 3 (загружает админ в /admin). Нет строки «הקראה:» — тест пропускается.
import { expect } from '@wdio/globals';
import { byText, expectVisibleText, scrollToText } from '../../helpers/ui.ts';
import { openPrayer, goToPage } from '../../helpers/nav.ts';
import { toHome } from '../../helpers/app.ts';
import { ensureNusach, nusachHeader, playerButton, recordingLine, shown, skipWith, NO_RECORDING } from '../_lib/app-0710.ts';

describe('Озвучка: запись привязана к נוסח', () => {
  afterEach(async () => { await toHome(); });

  it('RC-03 Смена נוסח в молитве → запись אשכנז не играет в ספרד; возврат אשכנזי — запись снова доступна #6a86f7eda7b2 @prod-safe', async function () {
    await openPrayer('arvit_ashkenaz', 'ערבית');
    await ensureNusach('אשכנזי');
    await goToPage(3, 15);
    await scrollToText('האזן להקראה');
    if (!(await shown(recordingLine()))) skipWith(this, `${NO_RECORDING} (ערבית אשכנז קטע 3)`);

    try {
      // 1. Меню נוסח → «ספרדי» → «החלף»: заголовок «ערבית (ספרדי)», у параллельного קטע записи нет.
      await ensureNusach('ספרדי');
      await expect(nusachHeader('ספרדי')).toBeDisplayed();   // iOS: label «בחירת נוסח. הנוסח המוצג: ספרדי» (11.10); в ספרד 16 страниц
      await scrollToText('האזן להקראה');
      await expectVisibleText('אין הקראה לקטע הזה');
      await expect(recordingLine()).not.toBeDisplayed();
      await expect(await playerButton('השמע')).toBeDisabled();
      await expect(byText('השהה')).not.toBeDisplayed();
    } finally {
      // 2. Вернуть «אשכנזי» (профиль не менялся — S-33 AC3), запись קטע 3 снова доступна.
      await ensureNusach('אשכנזי');
    }
    await expect(nusachHeader('אשכנזי')).toBeDisplayed();
    await goToPage(3, 15);
    await scrollToText('האזן להקראה');
    await expect(recordingLine()).toBeDisplayed();
    await expect(await playerButton('השמע')).toBeEnabled();
  });
});
